sys_script_email.script:
// Notification Email Script name: clm_trade_cta
// Table: x_birl3_clm_clm_new_credit_request
(function runMailScript(current, template, email, email_action, event) {

    // Builds the link from the current instance URL, so the same notification
    // works on abgdev, abgtest and prod after an update set move.
    var base = (gs.getProperty('glide.servlet.uri') || '').replace(/\/?$/, '/');
    var url  = base + 'uclm?id=view_my_credit_request';

    var h = '';
    h += '<table role="presentation" cellspacing="0" cellpadding="0" border="0" style="margin-top:28px;"><tbody><tr>';
    h += '<td align="center" style="background-color:#1a1a1a; border-radius:6px; border-bottom:3px solid #F3D54E;">';
    h += '<a href="' + url + '" style="display:inline-block; padding:12px 28px; font-size:13px; font-weight:700; letter-spacing:.5px; text-transform:uppercase; color:#ffffff; text-decoration:none;">Track Request</a>';
    h += '</td></tr></tbody></table>';

    template.print(h);

})(current, template, email, email_action, event);
